-- Hyprland config (Lua). Refer to https://wiki.hypr.land/Configuring/Start/
-- Palette: colors.lua (generated by matugen), falling back to colors-default.lua.

local home = os.getenv("HOME")
local hypr = home .. "/.config/hypr"

-- dofile instead of require so a reload always sees the newest generated palette
local function load_colors()
    for _, file in ipairs({ "colors.lua", "colors-default.lua" }) do
        local ok, palette = pcall(dofile, hypr .. "/" .. file)
        if ok and type(palette) == "table" then
            return palette
        end
    end
    return {}
end
local c = load_colors()


