local mainMod = "SUPER"

hl.bind(mainMod .. " + T",           hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + Q",           hl.dsp.window.close())
hl.bind(mainMod .. " + SHIFT + M",   hl.dsp.exit())
hl.bind(mainMod .. " + Escape",      hl.dsp.exec_cmd("qs ipc call power toggle"))
hl.bind(mainMod .. " + N",           hl.dsp.exec_cmd("qs ipc call controlcenter toggle"))
hl.bind(mainMod .. " + G",           hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V",           hl.dsp.exec_cmd("qs ipc call clipboard toggle"))  -- clipboard history
hl.bind(mainMod .. " + Tab",         hl.dsp.exec_cmd("qs ipc call overview toggle"))  -- workspace overview
hl.bind(mainMod .. " + period",      hl.dsp.exec_cmd("qs ipc call emoji toggle"))  -- emoji picker
hl.bind(mainMod .. " + SHIFT + V",   hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + D",           hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + Z",           hl.dsp.exec_cmd("firefox"))
hl.bind(mainMod .. " + B",           hl.dsp.exec_cmd("qs ipc call config bar toggle")) -- hide / bring back the bar
hl.bind(mainMod .. " + I",           hl.dsp.exec_cmd("qs ipc call settings toggle")) -- Settings from anywhere
hl.bind(mainMod .. " + W",           hl.dsp.exec_cmd("qs ipc call theme toggle"))
hl.bind(mainMod .. " + P",           hl.dsp.window.pseudo())          -- dwindle
hl.bind(mainMod .. " + J",           hl.dsp.layout("togglesplit"))    -- dwindle
hl.bind(mainMod .. " + F",           hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + F",   hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" })) -- maximize, keep bar

-- Screenshots: the Quickshell tool (toolbar, delay, preview card). If Quickshell
-- isn't running, `qs ipc` fails and the plain script takes over.
local shot = hypr .. "/scripts/screenshot.sh"
local function capture(mode, flag)
    return hl.dsp.exec_cmd("qs ipc call screenshot " .. mode .. " || " .. shot .. " " .. flag)
end
hl.bind("Print",                     capture("area", "--area"))
hl.bind("SHIFT + Print",             capture("screen", "--now"))
hl.bind("ALT + Print",               capture("window", "--win"))
hl.bind(mainMod .. " + K",           capture("toggle", "--area")) -- toolbar: mode, delay, copy/save
hl.bind(mainMod .. " + SHIFT + K",   capture("screen", "--now"))

-- Alt+Tab window switcher (Quickshell); releasing Alt picks the window
hl.bind("ALT + Tab",                 hl.dsp.exec_cmd("qs ipc call switcher next"))
hl.bind("ALT + SHIFT + Tab",         hl.dsp.exec_cmd("qs ipc call switcher prev"))
hl.bind("ALT + Alt_L",               hl.dsp.exec_cmd("qs ipc call switcher commit"), { release = true, transparent = true })

-- Move focus with mainMod + arrow keys
-- Move windows with mainMod + SHIFT + arrow keys
for key, dir in pairs({ left = "left", right = "right", up = "up", down = "down" }) do
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ direction = dir }))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ direction = dir }))
end

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Scratchpad
hl.bind(mainMod .. " + S",           hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S",   hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down",  hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",    hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272",   hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273",   hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness (the OSD is Quickshell)
local keys = { locked = true, repeating = true }
hl.bind("XF86AudioRaiseVolume",      hl.dsp.exec_cmd("qs ipc call osd volumeUp"),       keys)
hl.bind("XF86AudioLowerVolume",      hl.dsp.exec_cmd("qs ipc call osd volumeDown"),     keys)
hl.bind("XF86AudioMute",             hl.dsp.exec_cmd("qs ipc call osd volumeMute"),     keys)
hl.bind("XF86AudioMicMute",          hl.dsp.exec_cmd("qs ipc call osd micMute"),        keys)
hl.bind("XF86MonBrightnessUp",       hl.dsp.exec_cmd("qs ipc call osd brightnessUp"),   keys)
hl.bind("XF86MonBrightnessDown",     hl.dsp.exec_cmd("qs ipc call osd brightnessDown"), keys)

-- Requires playerctl
hl.bind("XF86AudioNext",             hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause",            hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",             hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",             hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


---------------------------
---- LAYER RULES (blur) ----
---------------------------

-- Quickshell windows blur what is behind them wherever their fill is translucent.
-- Full-screen overlays have a dim scrim, so they ignore low alpha (the scrim stays unblurred).
hl.layer_rule({
    name  = "qs-blur-bars",
    match = { namespace = "^(qs-bar|qs-dock|quickshell-(osd|notifications|screenshot-preview))$" },
    blur         = true,
    ignore_alpha = 0.2,
})
-- Power menu and goodbye screen: blur the whole screen, scrim included
-- Launcher: blur only behind the (translucent) card; the light dim scrim stays sharp
hl.layer_rule({
    name  = "qs-blur-launcher",
    match = { namespace = "^qs-launcher$" },
    blur         = true,
    ignore_alpha = 0.45,
})
hl.layer_rule({
    name  = "qs-blur-powermenu",
    match = { namespace = "^qs-powermenu$" },
    blur         = true,
    ignore_alpha = 0.01,
})
hl.layer_rule({
    name  = "qs-blur-panels",
    match = { namespace = "^(qs-panel)$" },
    blur         = true,
    ignore_alpha = 0.25,
})


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/

hl.window_rule({
    -- Ignore maximize requests from all apps
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

hl.window_rule({
    -- Video and browsers stay fully opaque
    name  = "opaque-media",
    match = { class = "^(mpv|firefox|zen|imv)$" },

    opacity = "1.0 override 1.0 override",
})

hl.window_rule({
    -- Small tools float
    name  = "float-tools",
    match = { class = "^(pavucontrol|org.pulseaudio.pavucontrol|nm-connection-editor|nwg-look|qt6ct|qt5ct)$" },

    float = true,
})

hl.window_rule({
    -- File pickers float
    name  = "float-file-dialogs",
    match = { title = "^(Open File|Save File|Open Folder)(.*)$" },

    float = true,
})
